import { stripBlueprintId } from '../../cards/card-blueprint';
// Generated by scripts/extract-card-data.mjs from the server's card definitions (npm runs it before build and test)
import generatedSides from '../../../generated/card-sides.json';

const SHADOW = new Set<string>(generatedSides.shadow);

/** Whether a card is a Shadow card (by its blueprint, foil and alternate images as the card itself). */
export function isShadowCard(blueprintId: string): boolean {
  return SHADOW.has(stripBlueprintId(blueprintId));
}
